use super::*;
use semio_framework_value::{ToValue,FromValue};
#[test]
fn native_identity_codecs_and_monotonic_overflow_match_corpus(){let value:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🧱️foundation/🔣️.json")).unwrap();for row in value["identities"].as_array().unwrap(){let revision=UiRevision(row["revision"].as_str().unwrap().parse().unwrap());assert_eq!(revision.try_next().map(|n|n.0.to_string()),row["next"].as_str().map(str::to_owned));assert_eq!(UiRevision::from_value(revision.to_value()).unwrap(),revision);assert_eq!(serde_json::from_value::<UiRevision>(serde_json::to_value(revision).unwrap()).unwrap(),revision);}let surface=SurfaceId::try_from("surface.ä🧬").unwrap();assert_eq!(serde_json::to_value(&surface).unwrap(),serde_json::json!("surface.ä🧬"));assert_eq!(SurfaceId::from_value(surface.to_value()).unwrap(),surface);assert_eq!(SurfaceId::try_from(surface.as_ref().to_owned()).unwrap(),surface);assert!(SurfaceId::try_from("a".repeat(513)).is_err());let mut allocator=UiNodeIdAllocator::default();for expected in 0..8{let id=allocator.try_allocate().unwrap();assert_eq!(id,UiNodeId(expected));assert_eq!(UiNodeId::from_value(id.to_value()).unwrap(),id);}assert_eq!(UiNodeIdAllocator(u64::MAX).try_allocate(),None);}
